begin;
insert into regulations (slug, title, category, summary, doc_number, authority, issued_date, status, status_note, source_url, source_filename, relevance, sort_order, published, featured, file_size_kb, download_url) values ('colliery-control-rules-2004', 'Colliery Control Rules, 2004', 'moc', 'The principal rules governing collieries, made by the Central Government under section 18 of the MMDR Act 1957. They regulate the opening of coal mines, seams and sections, the declaration of coal grades, production and dispatch returns, sub-division of a mining unit, and the Coal Controller''s powers of inspection. Read together with the Colliery Control (Amendment) Rules, 2026, which substituted rule 9.', 'G.S.R. 540(E)', 'Ministry of Coal', '2004-08-25', 'in_force', 'Principal rules; rule 9 substituted by G.S.R. 710(E) of 6 August 2026.', 'https://coalcontroller.gov.in/colliery-control-rules-2004', 'Colliery_Control_Rules_2004_principal_GSR540E.pdf', 1, 73, true, false, 283, 'https://docs.mangalamcoal.com/regs/colliery-control-rules-2004.pdf')
  on conflict (slug) do update set title = excluded.title, category = excluded.category, summary = excluded.summary, doc_number = excluded.doc_number, authority = excluded.authority, issued_date = excluded.issued_date, status = excluded.status, status_note = excluded.status_note, source_url = excluded.source_url, source_filename = excluded.source_filename, relevance = excluded.relevance, sort_order = excluded.sort_order, published = excluded.published, featured = excluded.featured, file_size_kb = excluded.file_size_kb, download_url = excluded.download_url;
insert into regulations (slug, title, category, summary, doc_number, authority, issued_date, status, status_note, source_url, source_filename, relevance, sort_order, published, featured, file_size_kb, download_url) values ('colliery-control-amendment-rules-2026', 'Colliery Control (Amendment) Rules, 2026 — prior approval to open a coal mine, seam or section', 'moc', 'Notified as G.S.R. 710(E) on 6 August 2026 under section 18 of the MMDR Act 1957, this amendment substitutes rule 9 of the Colliery Control Rules, 2004 and takes effect on publication. No colliery owner may open a coal mine, a seam or a section of a seam without the prior approval of the company''s Board (or, for a statutory corporation, its governing authority); owners that are neither must obtain the Coal Controller Organisation''s approval instead. In granting approval the Board must satisfy itself that every requisite permission and compliance is in place, and an intimation must reach the Coal Controller Organisation within fifteen days of opening. Sub-rule (3) applies the same requirement to restarting a mine, seam or section where operations have been discontinued for 180 days or more, and the Coal Controller Organisation maintains an indicative list of the permissions required.', 'G.S.R. 710(E)', 'Ministry of Coal', '2026-08-06', 'in_force', 'Substitutes rule 9 of the Colliery Control Rules, 2004; supersedes the rule 9 substituted by G.S.R. 917(E) of 23 December 2025.', 'https://coal.gov.in/', 'Colliery_Control_Amendment_Rules_GazetteNotif_10082026.pdf', 1, 74, true, false, 751, 'https://docs.mangalamcoal.com/regs/colliery-control-amendment-rules-2026.pdf')
  on conflict (slug) do update set title = excluded.title, category = excluded.category, summary = excluded.summary, doc_number = excluded.doc_number, authority = excluded.authority, issued_date = excluded.issued_date, status = excluded.status, status_note = excluded.status_note, source_url = excluded.source_url, source_filename = excluded.source_filename, relevance = excluded.relevance, sort_order = excluded.sort_order, published = excluded.published, featured = excluded.featured, file_size_kb = excluded.file_size_kb, download_url = excluded.download_url;
insert into regulations (slug, title, category, summary, doc_number, authority, issued_date, status, status_note, source_url, source_filename, relevance, sort_order, published, featured, file_size_kb, download_url) values ('colliery-control-amendment-rules-2025', 'Colliery Control (Amendment) Rules, 2025 (superseded on rule 9)', 'moc', 'Notified as G.S.R. 917(E) on 23 December 2025, this amendment first replaced the Coal Controller''s prior permission to open a coal mine with approval by the owner company''s Board. Its rule 9 has since been substituted again by G.S.R. 710(E) of 6 August 2026, which is the operative text; this notification is retained for the amendment history.', 'G.S.R. 917(E)', 'Ministry of Coal', '2025-12-23', 'superseded', 'Its rule 9 was substituted by G.S.R. 710(E) of 6 August 2026.', 'https://coal.gov.in/', 'Colliery_Control_Amendment_Rules_2025_23122025.pdf', 2, 75, true, false, 627, 'https://docs.mangalamcoal.com/regs/colliery-control-amendment-rules-2025.pdf')
  on conflict (slug) do update set title = excluded.title, category = excluded.category, summary = excluded.summary, doc_number = excluded.doc_number, authority = excluded.authority, issued_date = excluded.issued_date, status = excluded.status, status_note = excluded.status_note, source_url = excluded.source_url, source_filename = excluded.source_filename, relevance = excluded.relevance, sort_order = excluded.sort_order, published = excluded.published, featured = excluded.featured, file_size_kb = excluded.file_size_kb, download_url = excluded.download_url;
commit;
